INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65120868', 65120868, 'analyze_legacy', 'Kab. Mahakam Ulu', 'kabkota', 'Sekretariat DPRD', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Tulis Kantor Kegiatan Reses Masa Sidang III', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Mahakam Ulu (Kab.)', 156244000, 'November 2026', 'APBD', 1, 1, '1 Paket', 'Pekerjaan ini merupakan pengadaan Alat Tulis Kantor (ATK) dan jasa pendukung administrasi dalam rangka pelaksanaan kegiatan Reses DPRD Masa Sidang III. Pengadaan ini bertujuan untuk menunjang kelancaran kegiatan administrasi, dokumentasi, dan penyusunan laporan selama pelaksanaan reses DPRD Masa Sidang III sesuai kebutuhan masing-masing Daerah Pemilihan Dapil.', 'Spesifikasi pekerjaan meliputi penyediaan Alat Tulis Kantor (ATK) dan jasa pendukung administrasi untuk kegiatan Reses DPRD Masa Sidang III, dengan ketentuan sebagai berikut: Perlengkapan Alat Tulis Kantor, meliputi antara lain ballpoint, binder clip, isi stapler, stapler, map plastik, post it, sign here, dan trigonal clip, dengan kualitas standar perkantoran. Jasa Penggandaan Dokumen, berupa layanan fotocopy dokumen administrasi kegiatan reses. Jasa Cetak dan Penjilidan Dokumen, digunakan untuk bahan kegiatan dan laporan pelaksanaan reses. Pencetakan Spanduk Kegiatan, sebagai media informasi pelaksanaan kegiatan reses DPRD Masa Sidang III. Seluruh barang dan jasa disediakan sesuai kebutuhan kegiatan, standar kualitas yang berlaku, serta ketentuan peraturan perundang-undangan di bidang pengadaan barang/jasa pemerintah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1952184);
