INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65100404', 65100404, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT WAKIL PRESIDEN', 'Jasa Konsultansi Tenaga Ahli Kesehatan dan Gizi TP2S Tahun 2026', 'Jasa Konsultansi', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 5432631000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 paket', '1) Memantau pelaksanaan program/kegiatan terkait stunting pada sektor gizi dan kesehatan masyarakat yang dilaksanakan oleh Kementerian terkait. 2) Melakukan analisis dan evaluasi terhadap capaian pelaksanaan program P3S, terutama terkait dengan intervensi spesifik dan sensitif. 3) Melakukan kajian/studi/analisis lanjutan atau review terhadap isu-isu krusial terkait dengan P3S, terutama terkait dengan intervensi spesifik dan sensitif. 4) Menghasilkan output berupa laporan tertulis, publikasi, dan paparan, secara periodik berisi analisis dan rekomendasi kebijakan, diutamakan yang terkait dengan intervensi spesifik dan sensitif. 5) Menyiapkan bahan komunikasi, koordinasi dan advokasi yang efektif dengan kementerian/lembaga. 6) Menjaga profesionalitas, integritas, loyalitas, dan kesetiaan kepada pemberi kerja. 7) Melaksanakan tugas-tugas yang diberikan oleh Setwapres dan Team Leader dengan penuh tanggung jawab.', '1) Mempunyai pendidikan minimal S1 pada bidang Studi Kedokteran/Kesehatan Masyarakat/Gizi/Farmasi atau bidang lain yang relevan. 2) Mempunyai pengalaman 7 tahun atau S2 dengan pengalaman 5 tahun pada bidang Studi Kedokteran/ Kesehatan Masyarakat/Gizi/Farmasi atau bidang lain yang relevan. 3) Mempunyai pengalaman bekerja sama dengan Kementerian dan lembaga pemerintah daerah, dan mitra non-pemerintah. 4) Mempunyai keterampilan teknis menyusun perencanaan program/kegiatan, penyelesaian pelaporan, dan kerangka pemantauan dan evaluasi. 5) Mempunyai kemampuan advokasi, membangun kapasitas dan kolaborasi kerja, serta memiliki jejaring kerja yang luas pada Kementerian/Lembaga, pemerintah daerah, LSM, swasta, mitra pembangunan, dan pemangku kepentingan terkait lainnya. 6) Mempunyai pengalaman melakukan monitoring dan evaluasi terhadap isu-isu kesehatan terkait malnutrisi dan memberikan rekomendasai kepada pimpinan 7) Mampu membuat laporan tertulis terkait isu-isu kesehatan dan menyusun penyajian dalam presentasi dan laporan rutin dengan kualitas yang baik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1955593);
