INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65123816', 65123816, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Asisten Konsultan Manajemen Proyek Kerjasama', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 90000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Mengumpulkan data dukung dalam rangka pelaksanaan koordinasi perencanaan dan pengendalian Proyek Strategis Nasional; 2. Mengumpulkan data dukung dalam rangka pelaksanaan evaluasi proyek PSN dengan skema KPBU; 3. Melakukan koordinasi dengan pihak terkait mengenai progres/isu pada proyek yang menjadi Proyek Strategis Nasional; 4. Melakukan koordinasi dengan pihak terkait mengenai usulan proyek yang akan diusulkan menjadi Proyek Strategis Nasional; 5. Mempersiapkan dan melaksanakan rapat konfirmasi dengan Kantor Bersama KPBU atas penyusunan daftar proyek awal yang akan dicantumkan dalam Daftar Rencana Proyek Strategis Nasional; 6. Memberikan masukan dan penyiapan bahan dukung dalam proses penyusunan Suplemen PSN dalam Rencana Kerja Pemerintah; 7. Melakukan dokumentasi atas usulan proyek yang akan menjadi Proyek Strategis Nasional; 8. Melakukan dukungan pengelolaan dan pemutakhiran database Proyek Strategis Nasional;', '1. Pendidikan minimal Sarjana (S1) semua jurusan, yang dibuktikan dengan ijazah; 2. Memiliki pengalaman kerja minimal 6 (enam) bulan, yang dibuktikan dengan kontrak kerja/surat keterangan kerja; 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; 4. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 5. Mengikuti pelatihan dan sertifikasi level dasar KPBU yang diakui secara nasional, yang dibuktikan dengan sertifikat/surat keterangan kerja; 6. Memiliki pengalaman dalam bidang Proyek Infrastruktur, yang dibuktikan dengan surat keterangan kerja atau kontrak kerja; 7. Tidak sedang dalam kontrak dengan unit kerja lain di Kementerian PPN/Bappenas; 8. Berkewarganegaraan Indonesia, dibuktikan dengan Kartu Tanda Penduduk (KTP); 9. Memiliki Nomor Pokok Wajib Pajak (NPWP); dan 10. Dapat menerima sistem pembayaran gaji sesuai dengan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1957508);
